window.__finlexDocLoaded(10163,{"id":10163,"articles":[{"id":1000683,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Establishes the FASB Accounting Standards Codification (ASC) as the single source of authoritative nongovernmental US GAAP (alongside SEC rules/interpretive releases for SEC registrants).","seq":0},{"id":1000684,"no":"ASC 105-10","heading":"Single-Level GAAP Hierarchy & Non-Authoritative Guidance","text":"• Authoritative Sources (ASC 105-10-05-1): Only two levels exist — authoritative (the ASC + SEC guidance for registrants) and non-authoritative.\n• Analogizing (ASC 105-10-05-2): If a transaction is not specified in the ASC, first analogize to similar transactions within the ASC before consulting non-authoritative sources (CON 8, AICPA guides, IFRS).\n• True-and-Fair Override: Unlike IAS 1.19, US GAAP effectively prohibits departing from authoritative GAAP in SEC filings.","seq":1},{"id":1000685,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• IFRS (IAS 8.10–12) provides a formal hierarchy allowing management to look to other standard-setters (including US GAAP) when no IFRS applies; US GAAP centers strictly on the Codification.","seq":2},{"id":1000686,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
